// SPDX-License-Identifier: MIT
// Generate index.md, lessons/index.md, lessons/evidence.md, llms.txt, llms-full.txt and changes/ from
// cases/*.md, lessons/*.md, checklist.md (once it exists) and log.md, and keep two things in step in
// hand-written files (SYNCED): the repository URL and README's generated blocks (the AI disclosure and
// the current counts).
// Usage: node scripts/build.mjs          write the files
//        node scripts/build.mjs --check  write nothing; exit 1 if any generated file is out of date
//        --today YYYY-MM-DD             tests only: the reference date for the "may be outdated" mark.
// The reference date is the date of the newest log.md entry, never the clock, so the output does not
// change by itself; each update's log entry moves it, and that rebuild refreshes the mark.
// The case files and lesson pages are the source of truth; never edit the generated files by hand.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, posix, dirname } from 'node:path';
import {
  ROOT, REPO_SLUG, REPO_SLUGS, LESSON_NOTE, LESSON_LEGEND, LESSON_PAGES, listCases, parseCase, loadLessons, lessonMeta, sub, linksIn, refDefs,
  casesOf, mayBeOutdated, OUTDATED_MONTHS, modelFamily, CHECKLIST, CHANGES_DIR, logEntries, lessonPrints, questionPrints,
  renderChanges, parseChanges, isClaude, isAnthropic, namedModels, META_LABEL, PEOPLE_CHECK, splitModel, AI_ROLES,
} from './lib.mjs';

const check = process.argv.includes('--check');
const ti = process.argv.indexOf('--today');
const LOG = join(ROOT, 'log.md');
const logDate = () => (existsSync(LOG) ? readFileSync(LOG, 'utf8') : '').match(/^## (\d{4}-\d{2}-\d{2})\b/m)?.[1];
const TODAY = ti > 0 ? process.argv[ti + 1] : logDate();
if (ti > 0 && !/^\d{4}-\d{2}-\d{2}$/.test(TODAY || '')) { console.error('--today takes a date, YYYY-MM-DD'); process.exit(2); }
if (!TODAY) { console.error('cannot build: log.md needs an entry "## YYYY-MM-DD ..." (the reference date of the "may be outdated" mark)'); process.exit(1); }
const REPO = `https://github.com/${REPO_SLUG}`;
const RAW_BASE = `https://raw.githubusercontent.com/${REPO_SLUG}/main`;
// Hand-written files that name this repository: the build rewrites any older slug in REPO_SLUGS
// (scripts/lib.mjs) to REPO_SLUG and leaves every other URL alone. README.md also gets the generated
// blocks in README_BLOCKS, each between its markers.
const SYNCED = ['README.md', 'CONTRIBUTING.md', 'LICENSE-CONTENT.md', 'docs/field-reports.md', 'docs/try-it.md', '.github/ISSUE_TEMPLATE/config.yml',
  '.github/ISSUE_TEMPLATE/field-report.yml', 'lychee.toml'];
const GENERATED = '<!-- Generated by scripts/build.mjs from the case files and lesson pages. Do not edit by hand. -->';
// The checklist comes after the first ten cases; until then the generated files say so.
const HAS_CHECKLIST = existsSync(CHECKLIST);
const CHECKLIST_TEXT = HAS_CHECKLIST ? readFileSync(CHECKLIST, 'utf8') : '';

const cases = listCases().map(parseCase)
  .sort((a, b) => (b.meta.date || '').localeCompare(a.meta.date || '') || a.file.localeCompare(b.file));
const pages = loadLessons();
const caseByFile = new Map(cases.map(c => [c.file, c]));
const joinList = (xs, word) => xs.length < 2 ? xs.join('') : `${xs.slice(0, -1).join(', ')} ${word} ${xs.at(-1)}`;
const list = v => [v].flat().filter(Boolean).join(', ');

// Build only from sources that parse; anything else would silently drop a case, a page or a count.
const broken = [
  ...cases.filter(c => c.error).map(c => `${c.file}: ${c.error}`),
  ...LESSON_PAGES.filter(s => !pages.some(p => p.slug === s)).map(s => `lessons/${s}.md: missing`),
  ...pages.flatMap(p => p.lessons.filter(l => !lessonMeta(l).model).map(l => `${p.file}: ${l.id}: no "${META_LABEL}" line`)),
];
if (broken.length) {
  console.error(`cannot build; run node scripts/validate.mjs:\n${broken.map(b => '  ' + b).join('\n')}`);
  process.exit(1);
}

// One line per case, from the front matter only (docs/format.md "One line per case").
const caseLine = (c, prefix) => {
  const m = c.meta;
  return `- **${m.label}**: [${m.title}](${prefix}${c.file}) — ${m.case_type}: ${m.subject}; AI: ${list(m.ai_role)}; measured: ${list(m.measures)}; ` +
    `checked against: ${list(m.checked_against)}; sample: ${m.sample}; evidence: ${m.evidence}; author: ${m.author_relation}; ` +
    `cost: ${m.cost}. ${m.summary}`;
};

// Counts for one page or for all.
const count = lessons => {
  const by = (f, v) => lessons.filter(l => f(l) === v).length;
  return {
    n: lessons.length,
    stated: by(l => l.tag, 'stated'), ours: by(l => l.tag, 'ours'),
    mYes: by(l => lessonMeta(l).model, 'yes'), mPartly: by(l => lessonMeta(l).model, 'partly'), mNo: by(l => lessonMeta(l).model, 'no'),
    people: PEOPLE_CHECK.map(v => by(l => lessonMeta(l).people, v)),
  };
};
const prefixOf = p => p.lessons[0]?.id.split('-')[0] ?? '';
const all = pages.flatMap(p => p.lessons);

// The disclosure (owner, 2026-11-14), computed from the front matter: who drafts the text; which cases
// involve Claude models (named in `models`, or Claude Code in `tools`, which runs them); every case whose
// org or subject is Anthropic, the maker of the model that drafts the text; and the maintainer's own cases.
const named = c => namedModels(c.meta);
const claude = cases.filter(c => named(c).some(isClaude) || [c.meta.tools].flat().some(t => /\bClaude Code\b/.test(t || '')));
const noModels = cases.filter(c => !claude.includes(c) && !named(c).length);
const anthropic = cases.filter(c => isAnthropic(c.meta.org) || isAnthropic(c.meta.subject));
const ownCases = cases.filter(c => c.meta.author_relation === 'maintainer-own');
const labels = cs => cs.map(c => c.meta.label);
const DISCLOSURE = 'Disclosure: the cases and lessons are drafted by Claude, an Anthropic model, and reviewed by the maintainer. ' +
  `${noModels.length ? 'At least ' : ''}${claude.length} of the ${cases.length} cases involve Claude models or Claude Code, as builders, ` +
  `judges or models under test${claude.length ? ` (${labels(claude).join(', ')})` : ''}` +
  `${noModels.length ? `; ${noModels.length} ${noModels.length === 1 ? 'leaves' : 'leave'} the models unstated` : ''}. ` +
  (anthropic.length
    ? `Anthropic is the author or the subject of ${anthropic.length === 1 ? 'one case' : `${anthropic.length} cases`}: ${anthropic.map(c => c.meta.title).join('; ')}. `
    : 'No case yet has Anthropic as its author or subject. ') +
  (ownCases.length
    ? `${ownCases.length === 1 ? 'One case is' : `${ownCases.length} cases are`} the maintainer's own project${ownCases.length === 1 ? '' : 's'} ` +
      `(${joinList([...new Set(labels(ownCases))], 'and')}, marked maintainer-own): never independent evidence, and never counted toward a lesson's strength.`
    : 'No case is the maintainer\'s own project.');

// The case files a lesson cites, in "Cases" or "Against", with the lesson IDs.
const caseFileOf = target => target?.match(/(?:^|\/)cases\/([^#/\s]+\.md)/)?.[1];
const caseUse = new Map(cases.map(c => [c.file, []]));
for (const p of pages) for (const l of p.lessons) {
  const files = new Set(['Cases', 'Against'].flatMap(s => linksIn(sub(l, s) || '', p.refs).map(x => caseFileOf(x.target))).filter(Boolean));
  for (const f of files) caseUse.get(f)?.push(l.id);
}

// "May be outdated" (docs/format.md "Lessons"): tagged yes for model ability, newest case in "Cases" older than
// OUTDATED_MONTHS at the reference date (the newest log.md entry).
const outdated = new Set(pages.flatMap(p => p.lessons.filter(l =>
  mayBeOutdated(l, casesOf(l, p.refs).map(f => caseByFile.get(f)?.meta).filter(Boolean), TODAY)).map(l => l.id)));
const OUTDATED_NOTE = `"May be outdated" marks a lesson about what models can or cannot do (tagged "Depends on model ability: yes") ` +
  `whose most recent case (the later of its publication date and the end of its work) is more than ${OUTDATED_MONTHS} months older than the newest update in the log: newer models may no longer behave so; ` +
  're-check it against recent work before you rely on it.';
// "By model" (lessons/index.md): each model family the cases name (modelFamily in scripts/lib.mjs; a
// name with no rule there is its own family), the names behind it, its newest case, and the lessons
// tagged yes or partly for model ability whose cited cases ("Cases") name a model of that family. It
// reads the cases, not the Era, which gives only the newest family.
// Each lesson is listed under the roles the family's models played in its cited cases (the roles a case's
// `models` carry; for a case that names no model, its ai_role), so a model that only built pages in a
// benchmark is not read as evidence about judges.
const familyOf = n => modelFamily(n) ?? n;
const modelsOf = c => {
  const ms = [c.meta.models].flat().filter(x => x && x !== 'unstated').map(splitModel);
  return ms.length ? ms : [{ name: 'unstated', roles: [c.meta.ai_role].flat().filter(Boolean) }];
};
const families = new Map();
for (const c of cases) for (const { name } of modelsOf(c)) {
  const f = families.get(familyOf(name)) ?? { names: new Set(), newest: '', lessons: new Map() };
  f.names.add(name); if (String(c.meta.date) > f.newest) f.newest = String(c.meta.date);
  families.set(familyOf(name), f);
}
for (const p of pages) for (const l of p.lessons) if (['yes', 'partly'].includes(lessonMeta(l).model)) {
  const cited = casesOf(l, p.refs).map(f => caseByFile.get(f)).filter(Boolean);
  for (const { name, roles } of cited.flatMap(modelsOf)) {
    const ls = families.get(familyOf(name))?.lessons;
    if (!ls) continue;
    if (!ls.has(l.id)) ls.set(l.id, new Set());
    roles.forEach(r => ls.get(l.id).add(r));
  }
}
// "build: JDG-1, JDG-2; check: ACC-3": lessons grouped by the family's roles in their cases.
const byRole = lessons => {
  const groups = new Map();
  for (const [id, roles] of lessons) {
    const key = AI_ROLES.filter(r => roles.has(r)).join('/') || 'role unstated';
    groups.set(key, [...(groups.get(key) || []), id]);
  }
  return lessons.size ? `${lessons.size}: ${[...groups].map(([k, ids]) => `${k}: ${ids.join(', ')}`).join('; ')}` : '0: none';
};
for (const f of families.values()) f.row = byRole(f.lessons);
const familyRows = [...families].sort(([a, x], [b, y]) => (a === 'unstated') - (b === 'unstated') || y.newest.localeCompare(x.newest) || a.localeCompare(b));
// Families with the same newest case and the same lessons share one row (usually because the same
// cases name them; the row does not check that), which keeps lessons/index.md under INDEX_MAX_BYTES.
const familyGroups = [];
for (const [fam, f] of familyRows) {
  const g = fam !== 'unstated' && familyGroups.find(x => x.fams[0] !== 'unstated' && x.newest === f.newest && x.row === f.row);
  if (g) { g.fams.push(fam); f.names.forEach(n => g.names.add(n)); }
  else familyGroups.push({ fams: [fam], names: new Set(f.names), newest: f.newest, row: f.row });
}
const NEWEST_CASE = cases.map(c => String(c.meta.date)).sort().at(-1);
const MODEL_RULE = 'With a specific or a new model: process lessons (model ability: no) apply as they are. Start with the lessons tagged ' +
  'yes or partly whose cases name your model or its family in the role you use it for ("By model" in lessons/index.md lists ' +
  'each lesson under the roles the family played in its cases); treat those from other models or roles as ' +
  `things to re-check on yours, not tips. A model released after the newest case (published ${NEWEST_CASE}) has no evidence here yet. The lessons ` +
  'hold only what the cases show: no prompting advice, and no judgement of which look is better.';
const out = {};

// changes/<entry>.md (docs/format.md "Update log"): what each log entry added, changed or removed. Only the
// newest entry's file is rebuilt, from the previous entry's frozen state; older files must exist.
const entries = logEntries(readFileSync(LOG, 'utf8'));
const changesFile = e => join(CHANGES_DIR, `${e.slug}.md`);
for (const e of entries.slice(1)) {
  if (!existsSync(changesFile(e))) {
    console.error(`cannot build: changes/${e.slug}.md is missing; it records the state after "${e.head}" and cannot be rebuilt`);
    process.exit(1);
  }
}
const NEWEST = entries[0];
const prevEntry = entries[1] && { head: entries[1].head, state: parseChanges(readFileSync(changesFile(entries[1]), 'utf8')).state };
out[`changes/${NEWEST.slug}.md`] = renderChanges(NEWEST, prevEntry, lessonPrints(pages), questionPrints(CHECKLIST_TEXT),
  '<!-- Generated by scripts/build.mjs from the lesson pages, checklist.md and log.md. Do not edit by hand. -->');

// lessons/index.md
{
  const t = count(all);
  const rows = pages.map(p => {
    const c = count(p.lessons);
    return `| [${p.title}](${p.slug}.md) | ${prefixOf(p)} | ${c.n} | ${c.stated} | ${c.ours} | ${c.mYes} | ${c.mPartly} | ${c.mNo} | ${c.people.join(' | ')} |`;
  });
  // One line per page (IDs only; the lesson text is in evidence.md), so the index stays under INDEX_MAX_BYTES.
  const disagree = pages.map(p => [p, p.lessons.filter(l => /^Disagree:/.test(sub(l, 'Against') || '')).map(l => l.id)])
    .filter(([, ids]) => ids.length).map(([p, ids]) => `- [${p.title}](${p.slug}.md): ${ids.join(', ')}`);
  out['lessons/index.md'] = [
    GENERATED, '',
    '# Lessons by aspect', '',
    'Lessons on interfaces designed, built, changed or checked with AI, drawn from the cases in [the case index](../index.md). ' +
      'Each lesson is one line in our own words with a stable ID (the prefix names its page), the cases behind it, the ' +
      'evidence against it, whether it depends on model ability, and whether people checked the evidence. This page is ' +
      'a table of contents: to choose lessons, read [evidence.md](evidence.md) (one line per lesson), then open an aspect ' +
      'page only for the lessons you use.', '',
    LESSON_NOTE, '',
    'The legend of the tags, the Era and the strength rule heads every aspect page.', '',
    '## Aspects', '',
    `| Aspect | Prefix | Lessons | stated | ours | model yes | partly | no | people ${PEOPLE_CHECK.join(' | ')} |`,
    `|${' --- |'.repeat(8 + PEOPLE_CHECK.length)}`,
    ...rows,
    `| **All** | | ${t.n} | ${t.stated} | ${t.ours} | ${t.mYes} | ${t.mPartly} | ${t.mNo} | ${t.people.join(' | ')} |`, '',
    '"Model" counts the "Depends on model ability" tag; "people" the "Checked against people" tag.', '',
    '## May be outdated', '',
    OUTDATED_NOTE, '',
    ...(outdated.size ? pages.flatMap(p => p.lessons.filter(l => outdated.has(l.id)).map(l => `- **${l.id}** ([${p.title}](${p.slug}.md)) ${l.text}`)) : ['None at the newest update.']), '',
    '## By model', '',
    MODEL_RULE, '',
    'Families group the model names the cases give by maker, line and major version ("Claude Opus 4.6" and "Opus 4.8" are ' +
      'Claude Opus 4.x; "GPT-5.4" and "gpt-5.5" are GPT-5.x); a name with a line but no version, and an internal model, ' +
      'stay apart; unstated covers the cases that name no model. Lessons: those tagged yes or partly for model ability whose ' +
      'cited cases name a model of the family (a lesson\'s Era names only the newest), grouped by the role the family\'s models ' +
      'played in those cases (design, build, change, check, judge, simulate-user, as each case\'s front matter gives it; for ' +
      'unstated, the case\'s roles): a family listed only under build there was a model under test, not a judge. Newest case: the latest publication date among the cases that name it. Families with the same newest case and lessons share a row.', '',
    '| Model family | Names in the cases | Newest case | Lessons (model ability yes or partly), by the family\'s role |', '| --- | --- | --- | --- |',
    ...familyGroups.map(g => `| ${g.fams.join('; ')} | ${[...g.names].join('; ')} | ${g.newest} | ${g.row} |`), '',
    '## Where the cases disagree', '',
    'Lessons whose "Against" line opens with "Disagree:", a real split between cases; each one\'s line is in [evidence.md](evidence.md).', '',
    ...(disagree.length ? disagree : ['None recorded.']), '',
  ].join('\n');
}

// lessons/evidence.md: one line per lesson with only what choosing it needs (docs/format.md "Generated
// files"): tags, strength, the "may be outdated" mark, the cases it cites and those its "Against" cites.
// A maintainer-own case is marked "(own)" wherever it is named.
const nameOf = c => `${c.meta.label}${c.meta.author_relation === 'maintainer-own' ? ' (own)' : ''}`;
const companiesIn = (text, refs) => [...new Set(linksIn(text || '', refs).map(x => caseByFile.get(caseFileOf(x.target)))
  .filter(Boolean).map(nameOf))];
const shortAgainst = (text, refs) => {
  const names = companiesIn(text, refs);
  if (/^Disagree:/.test(text || '')) return `disagree: ${names.join(', ') || 'see page'}`;
  if (/^None found/.test(text || '')) return names.length ? `none found; a limit from ${names.join(', ')}` : 'none found';
  return names.join(', ') || 'no case linked, see page';
};
out['lessons/evidence.md'] = [
  GENERATED, '',
  '# Lesson evidence in one line each', '',
  `${all.length} lessons. This is the one file that lists every lesson (besides llms-full.txt, which holds everything). ` +
    'To choose lessons: scan this file, then open the aspect page (the heading link) only for the ' +
    'lessons you use; it holds the full "Against" line, the Era (years and newest model family) and the legend. Each line: ID, tag ' +
    '(stated by a source, or ours), the lesson, then model (does it depend on model ability), people (what checked its evidence: ' +
    'people, people in part, a checker, a model, or none but the author), strength, "may be outdated" where it applies, the cases it cites ("(own)" marks the ' +
    'maintainer\'s own project, never counted toward strength), and the cases its "Against" line cites.', '',
  ...pages.flatMap(p => [`## [${p.title}](${p.slug}.md)`, '',
    ...p.lessons.map(l => {
      const m = lessonMeta(l);
      return `- **${l.id}** [${l.tag}] ${l.text} Model ${m.model}; people ${m.people}; ${m.strength}` +
        `${outdated.has(l.id) ? '; may be outdated' : ''}. Cases: ${companiesIn(sub(l, 'Cases'), p.refs).join(', ')}. ` +
        `Against: ${shortAgainst(sub(l, 'Against'), p.refs)}.`;
    }), '']),
].join('\n');

// What the cases cover, from the front matter: counts by case type and by what AI did.
const tally = (key, vals) => vals.map(v => [v, cases.filter(c => [c.meta[key]].flat().includes(v)).length]).filter(([, n]) => n)
  .map(([v, n]) => `${v} ${n}`).join(', ');
const COVERED = `By type: ${tally('case_type', ['product', 'benchmark', 'study'])}. ` +
  `What AI did: ${tally('ai_role', ['design', 'build', 'change', 'check', 'judge', 'simulate-user'])}. ` +
  `Checked against: ${tally('checked_against', ['people', 'checker', 'model', 'none'])} (a case may count under several).`;

// index.md
out['index.md'] = [
  GENERATED, '',
  '# Index', '',
  `${cases.length} cases, newest first. Each line: the case's label (the name the lessons and the checklist use for it), title — case type (product, benchmark or study): the interface or set of interfaces; ` +
    'what AI did; what was measured; what the AI\'s output was checked against (people, an automated checker, a model judge); ' +
    'the sample; how far the claims can be checked; the author\'s stake in the tools (maintainer-own marks the maintainer\'s own ' +
    'project); the cost the source gives; a one-line summary.', '',
  `Lessons drawn from the cases, by aspect: [lessons/index.md](lessons/index.md) (${all.length} lessons on ` +
    `${pages.length} pages). ${HAS_CHECKLIST ? 'To measure a project: [checklist.md](checklist.md).' : 'The checklist an agent runs on a project comes after the first ten cases.'}`, '',
  `Cases covered: ${COVERED}`, '',
  ...cases.map(c => caseLine(c, 'cases/')), '',
].join('\n');

// Absolute links for llms-full.txt: reference links become inline links, and relative targets
// (resolved from `base`) become RAW_BASE URLs, in links and in reference definitions. Anchors and
// other schemes stay.
const RELATIVE = '(?![a-z][a-z0-9+.-]*:|#)';
const toRaw = (base, rel) => `${RAW_BASE}/${posix.normalize(base ? `${base}/${rel}` : rel)}`;
const absolute = (text, refs, base = 'lessons') => text
  .replace(/\[([^\]]+)\]\[([^\]]*)\]/g, (m, t, l) => { const x = refs.get((l || t).toLowerCase()); return x ? `[${t}](${x})` : m; })
  .replace(new RegExp(`\\]\\(${RELATIVE}([^)\\s]+)\\)`, 'gi'), (_, rel) => `](${toRaw(base, rel)})`)
  .replace(new RegExp(`^(\\[[^\\]]+\\]:\\s*)${RELATIVE}(\\S+)`, 'gim'), (_, label, rel) => `${label}${toRaw(base, rel)}`);
// A whole hand-written page for llms-full.txt: links made absolute, headings one level down
// (outside code blocks) so they sit under the file's own title. A reference definition goes into
// llms-full.txt once: `absolute` has made its links inline, so a definition an earlier page already
// gave (same label, same target) is dropped.
const defined = new Set();
const embed = rel => {
  let fence = false;
  const text = readFileSync(join(ROOT, rel), 'utf8').replace(/\r\n/g, '\n').trim();
  const dir = posix.dirname(rel) === '.' ? '' : posix.dirname(rel);
  return absolute(text, refDefs(text.split('\n')), dir).split('\n')
    .flatMap(l => {
      if (/^```/.test(l)) { fence = !fence; return [l]; }
      if (fence) return [l];
      const m = l.match(/^\[([^\]]+)\]:\s*(\S+)/);
      const def = m && `${m[1].toLowerCase()} ${m[2]}`;
      if (def) { if (defined.has(def)) return []; defined.add(def); return [l]; }
      return [/^#{1,5} /.test(l) ? `#${l}` : l];
    }).join('\n');
};

// llms-full.txt (built first: llms.txt states its size)
{
  // Each lesson with its sub-items, from the parsed page (whatever else sits between lessons).
  const lessonText = p => absolute(p.lessons.map(l => [p.lines[l.line - 1], ...l.subs.map(s => s.raw)].join('\n')).join('\n'), p.refs);
  out['llms-full.txt'] = [
    `# AI interfaces: every lesson, every case line${HAS_CHECKLIST ? ' and the checklist' : ''} in one file`, '',
    'Unofficial; company names describe the subject only. Summaries and lessons are our own words under CC BY 4.0. ' +
      `Source: ${REPO}`, '',
    DISCLOSURE, '',
    LESSON_NOTE.replace('[this collection](../index.md)', 'this collection'), '',
    LESSON_LEGEND, '',
    ...pages.flatMap(p => [`## ${p.title} (${p.slug}.md)`, '', p.intro, '', lessonText(p), '']),
    '## Cases', '',
    ...cases.map(c => caseLine(c, `${RAW_BASE}/cases/`)), '',
    ...(HAS_CHECKLIST ? [embed('checklist.md'), ''] : []),
  ].join('\n');
}
const fullKB = Math.round(Buffer.byteLength(out['llms-full.txt'], 'utf8') / 1024);
const fullKTokens = Math.round(Buffer.byteLength(out['llms-full.txt'], 'utf8') / 4000);
const evidenceKB = Math.round(Buffer.byteLength(out['lessons/evidence.md'], 'utf8') / 1024);
// Sizes of the checklist route's hand-written files, with LF line ends (as the repository holds them).
const APPLYING = join(ROOT, 'docs', 'applying-lessons.md');
const kbOf = p => existsSync(p) ? Math.round(Buffer.byteLength(readFileSync(p, 'utf8').replace(/\r\n/g, '\n'), 'utf8') / 1024) : 0;

// llms.txt (https://llmstxt.org). The no-warranty line follows the summary quote (owner, 2026-11-15); a test
// in test-validate.mjs checks it.
const NO_WARRANTY = 'No warranty: everything here is provided as it is. Before changing anything because of it, show the ' +
  'user each proposal with its source and evidence level and let the user choose; work on a branch or with a backup.';
out['llms.txt'] = [
  '# AI interfaces', '',
  '> Case studies and measurements on user interfaces designed, built, changed or checked with AI: what was measured, ' +
    'against whom (people, automated checkers or a model judge), what worked, what failed, and which part AI did versus ' +
    'rule-based tools and people. Lessons drawn from them by aspect.', '',
  NO_WARRANTY, '',
  'Unofficial; company names describe the subject only. The collection measures; it never says which look is better: ' +
    'taste stays with a person. A lesson\'s "Checked against people" tag says what checked its evidence: people (yes), ' +
    'people for part of it (partly), only deterministic checks (checker), only model judges or simulated users (model), ' +
    'or only the author\'s account (none); it hints at how far the lesson travels but is not a filter, so judge each ' +
    'lesson by its own words. Each case says how far its claims can be checked and what stake its author has in the tools: ' +
    'weigh it accordingly; a lesson that rests only on cases whose authors sell the tool is never rated strong, and the ' +
    'maintainer\'s own projects never count toward a lesson\'s strength.', '',
  MODEL_RULE, '',
  `${OUTDATED_NOTE} ${outdated.size ? `Marked now: ${[...outdated].join(', ')}.` : 'None is marked now.'} A lesson's Era gives the years of its cases and the newest model family among them.`, '',
  '<!-- disclosure: generated by scripts/build.mjs -->',
  DISCLOSURE,
  '<!-- /disclosure -->', '',
  '## How to use', '',
  ...(HAS_CHECKLIST
    ? [`- Before an interface change: run the [checklist](${RAW_BASE}/checklist.md) (about ${kbOf(CHECKLIST)} KB) on the project and change nothing. Each ` +
      'question has a Check to measure (static where no running page is allowed) and cites lesson IDs; its report gives a ' +
      'baseline for every count, so the same counts can be taken after the change. Its measuring notes and the report and ' +
      `record formats are the third file of this route: [docs/applying-lessons.md](${RAW_BASE}/docs/applying-lessons.md) ` +
      `(about ${kbOf(APPLYING)} KB). Open only the lessons and cases behind a gap.`,
      `- Learning from the lessons (how a project's agents build, change and check its interface): follow ` +
      `[docs/applying-lessons.md](${RAW_BASE}/docs/applying-lessons.md), which uses the lessons route below; its revisit ` +
      'section serves both routes.']
    : ['- The checklist an agent runs on a project (accessibility, contrast, clicks and screens per job, consistency counts) comes ' +
      'after the first ten cases; until then, use the lessons.']),
  `- Lessons, one route: read [lessons/evidence.md](${RAW_BASE}/lessons/evidence.md) (about ${evidenceKB} KB, the only file ` +
    'besides llms-full.txt that lists every lesson: one line each with tags, strength, cases and the cases against), then ' +
    'open an aspect page only for the lessons you use.',
  `- Open a case only when you need its detail. Each has "Who did what", "How it was checked", a Numbers table with ` +
    `the basis of each number, "What went wrong" and "Practices to copy". File format: [docs/format.md](${RAW_BASE}/docs/format.md).`,
  `- Once a prediction has met a real event (a change measured before and after, a problem a lesson foresaw or missed): ` +
    `tell what the ${HAS_CHECKLIST ? 'questions and lessons' : 'lessons'} foresaw and what they missed in a field report ([how](${RAW_BASE}/docs/field-reports.md)); show ` +
    'the user the exact text before posting.',
  `- Corrections: read [corrections.md](${RAW_BASE}/corrections.md) first on every revisit, even when nothing else is new: ` +
    'what this collection published wrong, between which dates, how to recognise it in a project and what to propose to ' +
    'its owner. Whoever ran a route while an entry was published should run the revisit again.',
  `- Revisit: the newest update is "${NEWEST.head}". For each [log.md](${RAW_BASE}/log.md) entry newer than your record's, ` +
    `read changes/<entry>.md (newest: [${NEWEST.slug}](${RAW_BASE}/changes/${NEWEST.slug}.md)), the lesson IDs and questions it ` +
    'added, changed or removed.',
  `- Relative links inside these files resolve against the raw URL of the file that holds them (under ${RAW_BASE}/).`, '',
  '## Lessons', '',
  `The aspect pages (tag counts per page: [lessons/index.md](${RAW_BASE}/lessons/index.md)). Choose lessons in ` +
    `[lessons/evidence.md](${RAW_BASE}/lessons/evidence.md) first; open a page only for the lessons you use.`, '',
  ...pages.map(p => `- [${p.title}](${RAW_BASE}/lessons/${p.slug}.md): ${p.lessons.length} lessons, ${prefixOf(p)}-n. ${p.intro}`), '',
  '## Cases', '',
  `- [The case index](${RAW_BASE}/index.md): ${cases.length} cases, one line each from its front matter (case type, the ` +
    'interface, what AI did, what was measured and against whom, the sample, evidence, the author\'s stake, cost, a summary). ' +
    'Read it to choose cases; open only the cases you need.', '',
  '## Optional', '',
  `- [Everything in one file](${RAW_BASE}/llms-full.txt): the single opt-in file that holds everything (every lesson ` +
    `with its sub-items, every case line${HAS_CHECKLIST ? ', the checklist' : ''}), for tools that cannot follow links. About ` +
    `${fullKB} KB (~${fullKTokens}k tokens): otherwise follow the route above.`,
  `- [Update log](${RAW_BASE}/log.md): what each update covered and changed, and why.`, '',
].join('\n');

// Hand-written files kept in step: this repository's URLs, and README's generated blocks.
const questions = (CHECKLIST_TEXT.match(/^\d+\. \*\*/gm) || []).length;
const README_BLOCKS = {
  disclosure: DISCLOSURE,
  contents: `Now: ${cases.length} cases (${[...cases].reverse().map(c => c.meta.label).join(', ')}), ${all.length} lessons on ` +
    `${pages.length} aspect pages, ${HAS_CHECKLIST ? `and a checklist of ${questions} questions.` : 'and no checklist yet (it comes after the first ten cases).'}`,
};
for (const rel of SYNCED) {
  const p = join(ROOT, rel);
  if (!existsSync(p)) continue;
  let t = readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
  for (const old of REPO_SLUGS.slice(1)) t = t.split(old).join(REPO_SLUG);
  if (rel === 'README.md') {
    for (const [name, text] of Object.entries(README_BLOCKS)) {
      const a = `<!-- ${name}: generated by scripts/build.mjs -->`, z = `<!-- /${name} -->`;
      const i = t.indexOf(a), j = t.indexOf(z);
      if (i < 0 || j < i) { console.error(`README.md: needs the markers ${a} and ${z}`); process.exit(1); }
      t = `${t.slice(0, i + a.length)}\n${text}\n${t.slice(j)}`;
    }
  }
  out[rel] = t;
}

// Write or check.
const stale = [];
for (const [rel, content] of Object.entries(out)) {
  const p = join(ROOT, rel);
  const old = existsSync(p) ? readFileSync(p, 'utf8').replace(/\r\n/g, '\n') : null;
  if (old === content) continue;
  stale.push(rel);
  if (!check) { mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, content); }
}
if (check && stale.length) {
  console.error(`out of date: ${stale.join(', ')}\nrun: node scripts/build.mjs`);
  process.exit(1);
}
console.log(check ? `generated files up to date (${Object.keys(out).length}).`
  : `${stale.length ? 'wrote ' + stale.join(', ') : 'nothing to write'}: ${cases.length} cases, ${all.length} lessons on ${pages.length} pages.`);
if (!check) for (const f of caseByFile.keys()) if (!caseUse.get(f).length) console.warn(`note: no lesson cites ${f}`);
